ee:variables.ee:set-variable:
%dw 2.0
output application/java
import trim from dw::core::Strings

var regions = ["Centro", "Occidente", "Norte", "Sur"]

fun statusOf(f) = f.status.statusCategory.key match {
    case "done" -> "Done"
    case "indeterminate" -> "In Progress"
    else -> "To Do"
}
// Plain-text lines of an Atlassian Document Format description
fun lines(desc) = flatten((desc.content default []) map ((p) -> (p.content default []) map ($.text default "")))
fun field(desc, prefix) = do {
    var hit = (lines(desc) filter ($ startsWith prefix))[0]
    ---
    if (hit == null) null else trim(hit[sizeOf(prefix) to -1])
}
fun blockLinks(f) = (f.issuelinks default []) filter ((l) -> l."type".name == "Blocks")
// On an issue's own links, "inwardIssue" means: this issue *is blocked by* inwardIssue
fun activeBlockers(f) = blockLinks(f) filter ((l) -> l.inwardIssue != null
                                         and l.inwardIssue.fields.status.statusCategory.key != "done")
fun blocksOthers(f) = blockLinks(f) filter ((l) -> l.outwardIssue != null)
fun hasBlockedByLink(f) = !isEmpty(blockLinks(f) filter ((l) -> l.inwardIssue != null))
fun isFlagged(f) = !isEmpty(f.customfield_10021 default [])
fun customer(f) = ((f.labels default []) filter ($ startsWith "MX-"))[0]
fun region(f) = ((f.labels default []) filter (regions contains $))[0]
fun ts(s) = if (isEmpty(s)) null
            else (((s as DateTime {format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ"}) >> "UTC") as String {format: "yyyy-MM-dd HH:mm:ss"})

var issueRows = (vars.allIssues filter ($.fields.issuetype.name != "Epic")) map (i) -> do {
    var f = i.fields
    var st = statusOf(f)
    var active = activeBlockers(f)
    // A flag counts only when no blocking link exists: links are the source of truth
    var blocked = st != "Done" and (!isEmpty(active) or (isFlagged(f) and !hasBlockedByLink(f)))
    var isPlat = i.key startsWith "PLAT-"
    ---
    {
        ISSUE_KEY: i.key,
        PROJECT: (i.key splitBy "-")[0],
        EPIC_KEY: f.parent.key default null,
        CUSTOMER_ID: customer(f),
        SUMMARY: f.summary,
        ISSUE_TYPE: f.issuetype.name,
        PRIORITY: f.priority.name default null,
        STATUS: if (blocked) "Blocked" else st,
        IS_BLOCKER: if (isPlat) (st != "Done" and !isEmpty(blocksOthers(f))) else blocked,
        BLOCKED_BY: if (blocked and !isEmpty(active)) active[0].inwardIssue.key else null,
        BLOCKED_REASON: if (!blocked) null
                        else if (!isEmpty(active)) "Bloqueado por " ++ active[0].inwardIssue.key ++ ": " ++ (active[0].inwardIssue.fields.summary default "")
                        else "Marcado como impedimento en Jira",
        ASSIGNEE: field(f.description, "Responsable:"),
        // Jira stamps Created as the API call time; the original open date lives in Start date
        CREATED_AT: if (isEmpty(f.customfield_10015)) ts(f.created) else (f.customfield_10015 ++ " 00:00:00"),
        DUE_DATE: f.duedate default null,
        RESOLVED_AT: ts(f.resolutiondate)
    }
}

var blockedEpics = (issueRows filter ($.STATUS == "Blocked" and $.EPIC_KEY != null)) map $.EPIC_KEY

var epicRows = (vars.allIssues filter ($.fields.issuetype.name == "Epic")) map (e) -> do {
    var f = e.fields
    var st = statusOf(f)
    ---
    {
        EPIC_KEY: e.key,
        NAME: f.summary,
        CUSTOMER_ID: customer(f),
        ORDER_ID: field(f.description, "Orden ERP:"),
        REGION: region(f),
        TARGET_GO_LIVE: f.duedate default null,
        STATUS: if (st == "Done") "Done" else if (blockedEpics contains e.key) "Blocked" else st
    }
}
---
{ issues: issueRows, epics: epicRows }
